import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.KobcctIO.js";const g=JSON.parse('{"title":"Delta Sync Algorithm and Incremental Backups","description":"","frontmatter":{},"headers":[],"relativePath":"guide/horizon/delta-sync-algorithm.md","filePath":"guide/horizon/delta-sync-algorithm.md"}'),o={name:"guide/horizon/delta-sync-algorithm.md"};function s(l,e,r,c,d,p){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="delta-sync-algorithm-and-incremental-backups" tabindex="-1">Delta Sync Algorithm and Incremental Backups <a class="header-anchor" href="#delta-sync-algorithm-and-incremental-backups" aria-label="Permalink to &quot;Delta Sync Algorithm and Incremental Backups&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Algorithm-Differential%20Delta-blue.svg" alt="Algorithm"><img src="https://img.shields.io/badge/Hashing-SHA--256-green.svg" alt="Hashing"><img src="https://img.shields.io/badge/Maintenance-Automatic%20Consolidation-orange.svg" alt="Maintenance"></div><p>The core technological pillar of Gens-Horizon is its differential synchronization (<strong>Delta Sync</strong>) engine implemented across <code>scanner.js</code>, <code>upload.js</code>, <code>sync.js</code>, and <code>cloud-operations.js</code>.</p><hr><h2 id="_1-high-performance-local-file-scanning-scanner-js" tabindex="-1">1. High-Performance Local File Scanning (<code>scanner.js</code>) <a class="header-anchor" href="#_1-high-performance-local-file-scanning-scanner-js" aria-label="Permalink to &quot;1. High-Performance Local File Scanning (`scanner.js`)&quot;">​</a></h2><p>Scanning a complex Minecraft instance (often containing upwards of 20,000 files spanning world region chunks, textures, and mod jars) must complete rapidly to ensure zero perceivable latency for the player:</p><ol><li><strong>Fast Pre-Check (mtime and byte size):</strong> Before running heavy SHA-256 cryptographic hashing, the scanner checks the modification timestamp (<code>mtimeMs</code>) and file size against the previous local manifest. If both match, the existing digest is preserved without reading the file from disk.</li><li><strong>Asynchronous Stream Hashing:</strong> When files are new or modified, their SHA-256 digest is calculated using streaming pipes (<code>fs.createReadStream</code>).</li><li><strong>Concurrency Limiting (<code>withConcurrency</code>):</strong> To avoid file descriptor exhaustion (<code>EMFILE: too many open files</code>), all file read operations are queued through a bounded concurrency worker pool (typically 16 to 32 concurrent handles).</li></ol><hr><h2 id="_2-difference-detection-and-delta-packaging-upload-js" tabindex="-1">2. Difference Detection and Delta Packaging (<code>upload.js</code>) <a class="header-anchor" href="#_2-difference-detection-and-delta-packaging-upload-js" aria-label="Permalink to &quot;2. Difference Detection and Delta Packaging (`upload.js`)&quot;">​</a></h2><p>When cloud synchronization is initiated:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Current Local Manifest ]  vs  [ Last Synchronized Manifest ]</span></span>\n<span class="line"><span>             |                                |</span></span>\n<span class="line"><span>             +----------------+---------------+</span></span>\n<span class="line"><span>                              |</span></span>\n<span class="line"><span>                              v</span></span>\n<span class="line"><span>                [ Three-Way Difference Split ]</span></span>\n<span class="line"><span>                - Added files (ADDED)</span></span>\n<span class="line"><span>                - Modified files (MODIFIED)</span></span>\n<span class="line"><span>                - Deleted files (DELETED)</span></span></code></pre></div><ol><li><strong>Delta Bundle Creation:</strong> Only files categorized as <code>ADDED</code> or <code>MODIFIED</code> are packed into a compact zip archive adhering to the naming standard: <code>GensHorizon_Delta_&lt;timestamp&gt;_&lt;hash&gt;.zip</code></li><li><strong>Metadata and Deletions Manifest:</strong> A companion lightweight metadata descriptor (<code>GensHorizon_Meta_&lt;timestamp&gt;.json</code>) explicitly details all <code>DELETED</code> file paths that must be removed locally on target machines.</li><li><strong>Targeted Upload:</strong> The resulting package (usually between a few kilobytes and 2 MB) is transferred to the designated cloud provider folder.</li></ol><hr><h2 id="_3-chronological-delta-application-sync-js" tabindex="-1">3. Chronological Delta Application (<code>sync.js</code>) <a class="header-anchor" href="#_3-chronological-delta-application-sync-js" aria-label="Permalink to &quot;3. Chronological Delta Application (`sync.js`)&quot;">​</a></h2><p>When a player switches to another computer to retrieve their progress:</p><ol><li><strong>Remote Index Fetching:</strong><code>sync.js</code> queries the cloud provider for all remote delta archives.</li><li><strong>Chronological Sorting:</strong> All deltas created subsequent to the local machine&#39;s recorded state are sequenced chronologically.</li><li><strong>Sequential Replay:</strong> For each pending delta: <ul><li>The archive is downloaded to a scratch folder.</li><li>Files are extracted, overwriting outdated local equivalents.</li><li>Files specified in the deletion manifest are purged from disk.</li><li>The local manifest index is updated.</li></ul></li><li><strong>Validation:</strong> The local instance is now an exact replica of the state saved on the previous machine.</li></ol><hr><h2 id="_4-automatic-pruning-and-consolidation-cloud-operations-js" tabindex="-1">4. Automatic Pruning and Consolidation (<code>cloud-operations.js</code>) <a class="header-anchor" href="#_4-automatic-pruning-and-consolidation-cloud-operations-js" aria-label="Permalink to &quot;4. Automatic Pruning and Consolidation (`cloud-operations.js`)&quot;">​</a></h2><p>Over months of active gameplay, small delta packages can accumulate. To prevent cloud storage clutter and API rate limiting:</p><ul><li><strong><code>getCloudIndexAndCleanDuplicates()</code>:</strong> Inspects remote folders, identifies orphaned artifacts, and cleans up accidental duplicates caused by aborted network calls.</li><li><strong>Consolidation Threshold (<code>deltaCleanupThreshold</code>):</strong> When accumulated delta archives exceed the configured threshold (default: 10 sessions), the engine merges the entire history into a fresh standalone baseline archive (<code>GensHorizon_Backup_&lt;timestamp&gt;.zip</code>) and removes older redundant delta files.</li></ul>',20)])])}const u=a(o,[["render",s]]);export{g as __pageData,u as default};
